package org.jiuyun.input;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.provider.Settings;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.graphics.Color;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 private String asset(String name)throws Exception{try(java.io.InputStream in=getAssets().open(name)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(35,60,35,40);layout.setBackgroundColor(Color.rgb(247,248,245));scroll.addView(layout);
 TextView title=new TextView(this);title.setText("玖云输入法");title.setTextSize(30);title.setTextColor(Color.rgb(79,116,96));layout.addView(title);TextView note=new TextView(this);note.setText("双拼优先，一字两键。\n8 套内置方案，可自定义声韵母键位。\n原型词库覆盖有限，不申请网络权限。\n");layout.addView(note);
 Button enable=new Button(this);enable.setText("1. 启用玖云输入法");enable.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS)));layout.addView(enable);Button choose=new Button(this);choose.setText("2. 切换到玖云");choose.setOnClickListener(v->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker());layout.addView(choose);
 try{JSONArray schemes=new JSONArray(asset("schemes.json"));List<String> names=new ArrayList<>();for(int i=0;i<schemes.length();i++)names.add(schemes.getJSONObject(i).getString("name"));names.add("全拼输入");Spinner picker=new Spinner(this);picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));layout.addView(picker);EditText json=new EditText(this);json.setTextSize(12);json.setMinLines(5);json.setMaxLines(10);json.setSingleLine(false);json.setText(getSharedPreferences("jiuyun_config",MODE_PRIVATE).getString("custom",schemes.getJSONObject(0).toString(2)));
 Button apply=new Button(this);apply.setText("使用所选预设");apply.setOnClickListener(v->{try{String val=picker.getSelectedItemPosition()==schemes.length()?"full":schemes.getJSONObject(picker.getSelectedItemPosition()).toString();getSharedPreferences("jiuyun_config",MODE_PRIVATE).edit().putString("scheme",val).apply();if(!val.equals("full"))json.setText(new JSONObject(val).toString(2));Toast.makeText(this,"已保存，下次打开键盘生效",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_SHORT).show();}});layout.addView(apply);
 TextView tip=new TextView(this);tip.setText("自定义：在下方编辑方案 JSON，或粘贴从网页版导出的方案。initials 为声母，finals 为韵母，zeroRule 为零声母规则。");layout.addView(tip);layout.addView(json);Button custom=new Button(this);custom.setText("保存并启用自定义方案");custom.setOnClickListener(v->{try{JSONObject s=new JSONObject(json.getText().toString());Shuangpin.validate(s);getSharedPreferences("jiuyun_config",MODE_PRIVATE).edit().putString("scheme",s.toString()).putString("custom",s.toString(2)).apply();Toast.makeText(this,"自定义方案已保存，下次打开键盘生效",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"无效方案："+e.getMessage(),Toast.LENGTH_LONG).show();}});layout.addView(custom);}catch(Exception e){TextView error=new TextView(this);error.setText("方案加载失败："+e.getMessage());layout.addView(error);}
 EditText test=new EditText(this);test.setHint("在这里试试 nihc → 你好（小鹤）");test.setMinLines(3);layout.addView(test);setContentView(scroll);
 }
}
